import { zodResolver } from "@hookform/resolvers/zod";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { navigate } from "raviger";
import { useEffect } from "react";
import { useForm } from "react-hook-form";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";
import { z } from "zod";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

import Page from "@/components/Common/Page";
import { FormSkeleton } from "@/components/Common/SkeletonLoading";

import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";
import {
  SCHEDULABLE_RESOURCE_TYPE_COLORS,
  SchedulableResourceType,
} from "@/types/scheduling/schedule";
import {
  TokenCategoryCreate,
  TokenCategoryRead,
  TokenCategoryUpdate,
} from "@/types/tokens/tokenCategory/tokenCategory";
import tokenCategoryApi from "@/types/tokens/tokenCategory/tokenCategoryApi";

export default function TokenCategoryForm({
  facilityId,
  tokenCategoryId,
  onSuccess,
}: {
  facilityId: string;
  tokenCategoryId?: string;
  onSuccess?: (tokenCategory: TokenCategoryRead) => void;
}) {
  const { t } = useTranslation();

  const isEditMode = Boolean(tokenCategoryId);

  const { data: existingData, isFetching } = useQuery({
    queryKey: ["tokenCategory", tokenCategoryId],
    queryFn: query(tokenCategoryApi.get, {
      pathParams: {
        facility_id: facilityId,
        id: tokenCategoryId!,
      },
    }),
    enabled: isEditMode,
  });

  if (isEditMode && isFetching) {
    return (
      <Page title={t("edit_token_category")} hideTitleOnPage>
        <div className="container mx-auto max-w-3xl">
          <div className="mb-6">
            <h1 className="text-xl font-semibold text-gray-900">
              {t("edit_token_category")}
            </h1>
          </div>
          <FormSkeleton rows={4} />
        </div>
      </Page>
    );
  }

  return (
    <Page
      title={isEditMode ? t("edit_token_category") : t("create_token_category")}
      hideTitleOnPage
    >
      <div className="container mx-auto max-w-3xl">
        <div className="mb-6">
          <h1 className="text-xl font-semibold text-gray-900">
            {isEditMode ? t("edit_token_category") : t("create_token_category")}
          </h1>
          {isEditMode && (
            <p className="text-sm text-gray-500">
              {t("edit_token_category_description")}
            </p>
          )}
        </div>
        <TokenCategoryFormContent
          facilityId={facilityId}
          tokenCategoryId={tokenCategoryId}
          existingData={existingData}
          onSuccess={onSuccess}
          containerClassName="rounded-lg border border-gray-200 bg-white p-6"
        />
      </div>
    </Page>
  );
}

export function TokenCategoryFormContent({
  facilityId,
  tokenCategoryId,
  existingData,
  containerClassName,
  onSuccess = () => navigate(`/facility/${facilityId}/settings/token_category`),
  onCancel = () => navigate(`/facility/${facilityId}/settings/token_category`),
  disableButtons = false,
  externalSubmitRef,
}: {
  facilityId: string;
  tokenCategoryId?: string;
  existingData?: TokenCategoryRead;
  containerClassName?: string;
  onSuccess?: (tokenCategory: TokenCategoryRead) => void;
  onCancel?: () => void;
  disableButtons?: boolean;
  externalSubmitRef?: React.RefObject<(() => void) | null>;
}) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const isEditMode = Boolean(tokenCategoryId);

  const formSchema = z.object({
    name: z.string().trim().min(1, t("field_required")),
    resource_type: z.enum(SchedulableResourceType),
    shorthand: z
      .string()
      .trim()
      .min(1, t("field_required"))
      .max(5, t("maximum_characters_allowed", { count: 5 })),
  });

  const form = useForm({
    resolver: zodResolver(formSchema),
    defaultValues:
      isEditMode && existingData
        ? {
            name: existingData.name,
            resource_type: existingData.resource_type,
            shorthand: existingData.shorthand,
          }
        : {
            name: "",
            resource_type: SchedulableResourceType.Practitioner,
            shorthand: "",
          },
  });

  const { mutate: createTokenCategory, isPending: isCreating } = useMutation({
    mutationFn: mutate(tokenCategoryApi.create, {
      pathParams: { facility_id: facilityId },
    }),
    onSuccess: (tokenCategory: TokenCategoryRead) => {
      queryClient.invalidateQueries({ queryKey: ["tokenCategories"] });
      toast.success(t("token_category_created_successfully"));
      onSuccess?.(tokenCategory);
    },
  });

  const { mutate: updateTokenCategory, isPending: isUpdating } = useMutation({
    mutationFn: mutate(tokenCategoryApi.update, {
      pathParams: {
        facility_id: facilityId,
        id: tokenCategoryId || "",
      },
    }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tokenCategories"] });
      queryClient.invalidateQueries({
        queryKey: ["tokenCategory", tokenCategoryId],
      });
      toast.success(t("token_category_updated_successfully"));
      navigate(`/facility/${facilityId}/settings/token_category`);
    },
  });

  const isPending = isCreating || isUpdating;

  function onSubmit(data: z.infer<typeof formSchema>) {
    if (isEditMode && tokenCategoryId) {
      const updatePayload: TokenCategoryUpdate = {
        name: data.name,
        resource_type: data.resource_type,
        shorthand: data.shorthand,
      };
      updateTokenCategory(updatePayload);
    } else {
      const createPayload: TokenCategoryCreate = {
        name: data.name,
        resource_type: data.resource_type,
        shorthand: data.shorthand,
      };
      createTokenCategory(createPayload);
    }
  }

  useEffect(() => {
    if (externalSubmitRef) {
      externalSubmitRef.current = () => {
        form.handleSubmit(onSubmit)();
      };
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [externalSubmitRef]);

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <div className={containerClassName}>
          <div className="space-y-4">
            <FormField
              control={form.control}
              name="name"
              render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("name")}</FormLabel>
                  <FormControl>
                    <Input
                      placeholder={t("enter_token_category_name")}
                      {...field}
                    />
                  </FormControl>
                  <FormDescription>
                    {t("token_category_name_description")}
                  </FormDescription>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="resource_type"
              render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("resource_type")}</FormLabel>
                  <Select
                    onValueChange={field.onChange}
                    defaultValue={field.value}
                  >
                    <FormControl>
                      <SelectTrigger>
                        <SelectValue placeholder={t("select_resource_type")} />
                      </SelectTrigger>
                    </FormControl>
                    <SelectContent>
                      {Object.keys(SCHEDULABLE_RESOURCE_TYPE_COLORS).map(
                        (type) => (
                          <SelectItem key={type} value={type}>
                            {t(type)}
                          </SelectItem>
                        ),
                      )}
                    </SelectContent>
                  </Select>
                  <FormDescription>
                    {t("resource_type_description")}
                  </FormDescription>
                  <FormMessage />
                </FormItem>
              )}
            />

            <FormField
              control={form.control}
              name="shorthand"
              render={({ field }) => (
                <FormItem>
                  <FormLabel aria-required>{t("shorthand")}</FormLabel>
                  <FormControl>
                    <Input placeholder={t("enter_shorthand")} {...field} />
                  </FormControl>
                  <FormDescription>
                    {t("shorthand_description")}
                  </FormDescription>
                  <FormMessage />
                </FormItem>
              )}
            />
          </div>
        </div>

        {!disableButtons && (
          <div className="flex justify-end gap-4">
            <Button type="button" variant="outline" onClick={onCancel}>
              {t("cancel")}
            </Button>
            <Button type="submit" disabled={isPending}>
              {isPending ? t("saving") : isEditMode ? t("update") : t("create")}
            </Button>
          </div>
        )}
      </form>
    </Form>
  );
}

import { useQuery } from "@tanstack/react-query";
import { Link } from "raviger";
import { useTranslation } from "react-i18next";

import CareIcon from "@/CAREUI/icons/CareIcon";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { EmptyState } from "@/components/ui/empty-state";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

import Page from "@/components/Common/Page";
import {
  CardGridSkeleton,
  TableSkeleton,
} from "@/components/Common/SkeletonLoading";

import { ActionButtons } from "@/pages/Facility/settings/ActionButtons";

import useFilters from "@/hooks/useFilters";

import query from "@/Utils/request/query";
import { getPermissions } from "@/common/Permissions";
import { usePermissions } from "@/context/PermissionContext";
import useCurrentFacility from "@/pages/Facility/utils/useCurrentFacility";
import { SCHEDULABLE_RESOURCE_TYPE_COLORS } from "@/types/scheduling/schedule";
import { TokenCategoryRead } from "@/types/tokens/tokenCategory/tokenCategory";
import tokenCategoryApi from "@/types/tokens/tokenCategory/tokenCategoryApi";

function TokenCategoryCard({
  tokenCategory,
  facilityId,
}: {
  tokenCategory: TokenCategoryRead;
  facilityId: string;
}) {
  const { t } = useTranslation();
  return (
    <Card>
      <CardContent className="p-6">
        <div className="mb-4 flex flex-wrap flex-col md:flex-row items-start justify-between gap-2">
          <div>
            <div className="mb-2 flex items-center gap-2">
              <Badge
                variant={
                  SCHEDULABLE_RESOURCE_TYPE_COLORS[tokenCategory.resource_type]
                }
              >
                {t(tokenCategory.resource_type)}
              </Badge>
            </div>
            <h3 className="font-medium text-gray-900 text-lg">
              {t("name")}: {tokenCategory.name}
            </h3>
            {tokenCategory.shorthand && (
              <p className="mt-1 text-sm text-gray-500">
                {t("shorthand")}: {tokenCategory.shorthand}
              </p>
            )}
          </div>
          <div className="ml-auto flex flex-wrap gap-2">
            <TokenCategoryActions
              tokenCategory={tokenCategory}
              facilityId={facilityId}
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

export default function TokenCategoryList({
  facilityId,
}: {
  facilityId: string;
}) {
  const { t } = useTranslation();
  const { qParams, updateQuery, Pagination, resultsPerPage } = useFilters({
    limit: 15,
    disableCache: true,
    defaultQueryParams: {
      status: "active",
    },
  });
  const { facility } = useCurrentFacility();
  const { hasPermission } = usePermissions();
  const { canWriteTokenCategory } = getPermissions(
    hasPermission,
    facility?.permissions ?? [],
  );

  const { data: response, isLoading } = useQuery({
    queryKey: ["tokenCategories", qParams],
    queryFn: query.debounced(tokenCategoryApi.list, {
      pathParams: {
        facility_id: facilityId,
      },
      queryParams: {
        limit: resultsPerPage,
        offset: ((qParams.page || 1) - 1) * resultsPerPage,
        status: qParams.status,
        name: qParams.search,
      },
    }),
  });

  const tokenCategories = response?.results || [];

  return (
    <Page title={t("token_categories")} hideTitleOnPage>
      <div className="container mx-auto">
        <div className="mb-4">
          <h1 className="text-2xl font-bold text-gray-700">
            {t("token_categories")}
          </h1>
          <div className="mb-6 flex sm:flex-row sm:items-center sm:justify-between flex-col gap-4">
            <div>
              <p className="text-gray-600 text-sm">
                {t("manage_token_categories")}
              </p>
            </div>
            {canWriteTokenCategory && (
              <Button>
                <Link
                  basePath="/"
                  href={`/facility/${facilityId}/settings/token_category/new`}
                >
                  <CareIcon icon="l-plus" className="mr-2" />
                  {t("add_token_category")}
                </Link>
              </Button>
            )}
          </div>

          <div className="flex flex-col md:flex-row justify-between items-start gap-4 mb-4">
            <div className="w-full md:w-auto">
              <div className="relative w-full md:w-auto">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">
                  <CareIcon icon="l-search" className="size-5" />
                </span>
                <Input
                  placeholder={t("search_token_categories")}
                  value={qParams.search || ""}
                  onChange={(e) =>
                    updateQuery({ search: e.target.value || undefined })
                  }
                  className="w-full md:w-[300px] pl-10"
                />
              </div>
            </div>
            {/* <div className="flex flex-col sm:flex-row items-stretch gap-2 w-full sm:w-auto">
              <div className="flex-1 sm:flex-initial sm:w-auto">
                <FilterSelect
                  value={qParams.status || ""}
                  onValueChange={(value) => updateQuery({ status: value })}
                  options={Object.values(SchedulableResourceType)}
                  label="status"
                  onClear={() => updateQuery({ status: undefined })}
                />
              </div>
            </div> */}
          </div>
        </div>

        {isLoading ? (
          <>
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3 md:hidden">
              <CardGridSkeleton count={4} />
            </div>
            <div className="hidden md:block">
              <TableSkeleton count={5} />
            </div>
          </>
        ) : tokenCategories.length === 0 ? (
          <EmptyState
            icon={
              <CareIcon icon="l-folder-open" className="text-primary size-6" />
            }
            title={t("no_token_categories_found")}
            description={t("no_token_categories_description")}
          />
        ) : (
          <>
            {/* Mobile Card View */}
            <div className="grid gap-4 md:hidden">
              {tokenCategories.map((tokenCategory: TokenCategoryRead) => (
                <TokenCategoryCard
                  key={tokenCategory.id}
                  tokenCategory={tokenCategory}
                  facilityId={facilityId}
                />
              ))}
            </div>
            {/* Desktop Table View */}
            <div className="hidden md:block">
              <div className="rounded-lg border">
                <Table>
                  <TableHeader className="bg-gray-100">
                    <TableRow>
                      <TableHead>{t("name")}</TableHead>
                      <TableHead>{t("resource_type")}</TableHead>
                      <TableHead>{t("shorthand")}</TableHead>
                      <TableHead>{t("actions")}</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody className="bg-white">
                    {tokenCategories.map((tokenCategory: TokenCategoryRead) => (
                      <TableRow key={tokenCategory.id} className="divide-x">
                        <TableCell className="font-medium">
                          {tokenCategory.name}
                          {tokenCategory.default && (
                            <Badge className="ml-2">{t("default")}</Badge>
                          )}
                        </TableCell>
                        <TableCell>
                          <Badge
                            variant={
                              SCHEDULABLE_RESOURCE_TYPE_COLORS[
                                tokenCategory.resource_type
                              ]
                            }
                          >
                            {t(tokenCategory.resource_type)}
                          </Badge>
                        </TableCell>
                        <TableCell>{tokenCategory.shorthand || "-"}</TableCell>
                        <TableCell>
                          <div className="flex gap-2">
                            <TokenCategoryActions
                              tokenCategory={tokenCategory}
                              facilityId={facilityId}
                            />
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          </>
        )}

        {response && response.count > resultsPerPage && (
          <div className="mt-4 flex justify-center">
            <Pagination totalCount={response.count} />
          </div>
        )}
      </div>
    </Page>
  );
}

function TokenCategoryActions({
  tokenCategory,
  facilityId,
}: {
  tokenCategory: TokenCategoryRead;
  facilityId: string;
}) {
  const { hasPermission } = usePermissions();
  const { facility } = useCurrentFacility();
  const { canWriteTokenCategory } = getPermissions(
    hasPermission,
    facility?.permissions ?? [],
  );
  return (
    <ActionButtons
      editPath={
        canWriteTokenCategory
          ? `/facility/${facilityId}/settings/token_category/${tokenCategory.id}/edit`
          : undefined
      }
      viewPath={`/facility/${facilityId}/settings/token_category/${tokenCategory.id}`}
    />
  );
}

import { SchedulableResourceType } from "@/types/scheduling/schedule";
import { UserReadMinimal } from "@/types/user/user";

export interface TokenCategory {
  id: string;
  name: string;
  resource_type: SchedulableResourceType;
  shorthand: string;
}

export type TokenCategoryCreate = Omit<TokenCategory, "id">;

export type TokenCategoryRead = TokenCategory & {
  default: boolean;
};

export interface TokenCategoryUpdate {
  name: string;
  resource_type: SchedulableResourceType;
  shorthand: string;
}

export interface TokenCategoryRetrieveSpec extends TokenCategoryRead {
  created_by: UserReadMinimal;
  updated_by: UserReadMinimal;
}

import { HttpMethod, PaginatedResponse, Type } from "@/Utils/request/types";

import {
  TokenCategoryCreate,
  TokenCategoryRead,
  TokenCategoryUpdate,
} from "@/types/tokens/tokenCategory/tokenCategory";

export default {
  list: {
    path: "/api/v1/facility/{facility_id}/token/category/",
    method: HttpMethod.GET,
    TRes: Type<PaginatedResponse<TokenCategoryRead>>(),
  },
  get: {
    path: "/api/v1/facility/{facility_id}/token/category/{id}/",
    method: HttpMethod.GET,
    TRes: Type<TokenCategoryRead>(),
  },
  create: {
    path: "/api/v1/facility/{facility_id}/token/category/",
    method: HttpMethod.POST,
    TRes: Type<TokenCategoryRead>(),
    TBody: Type<TokenCategoryCreate>(),
  },
  update: {
    path: "/api/v1/facility/{facility_id}/token/category/{id}/",
    method: HttpMethod.PUT,
    TRes: Type<TokenCategoryRead>(),
    TBody: Type<TokenCategoryUpdate>(),
  },
  setDefault: {
    path: "/api/v1/facility/{facility_id}/token/category/{id}/set_default/",
    method: HttpMethod.POST,
    TRes: Type<TokenCategoryRead>(),
  },
} as const;

